async (page) => {
  const results = []
  const check = (condition, label) => { if (!condition) throw new Error(`FAIL: ${label}`); results.push(label); console.log(`PASS: ${label}`) }
  const state = () => page.evaluate(() => JSON.parse(localStorage.getItem('phyqgen.prototype.v1') || '{}'))
  const logout = async () => {
    await page.locator('.user-info').hover()
    await page.getByRole('menuitem', { name: '退出登录', exact: true }).click()
    await page.getByRole('dialog', { name: '提示', exact: true }).getByRole('button', { name: '确定', exact: true }).click()
    await page.waitForURL('**/login')
  }
  await logout()
  await page.getByRole('tab', { name: '注册', exact: true }).click()
  const panel = page.getByRole('tabpanel', { name: '注册', exact: true })
  check(await panel.getByRole('combobox').count() === 0, '普通注册表单没有角色与管理员授权选项')
  await panel.getByPlaceholder('请输入用户名（3-50字符）', { exact: true }).fill('audit_registered')
  await panel.getByPlaceholder('请输入邮箱（可选）', { exact: true }).fill('registered@example.com')
  await panel.getByPlaceholder('请输入密码（至少6字符）', { exact: true }).fill('Register123')
  await panel.getByPlaceholder('请再次输入密码', { exact: true }).fill('Register123')
  await page.screenshot({ path: 'output/playwright/teacher-registration.png', fullPage: true })
  await panel.getByRole('button', { name: '注册', exact: true }).click()
  await page.waitForURL('**/overview')
  check((await state()).users.find(u => u.username === 'audit_registered').role === 'TEACHER', '普通注册仅创建教师并自动进入教师工作台')
  await page.goto('http://localhost:5173/admin/users')
  await page.waitForURL('**/overview')
  check(page.url().endsWith('/overview'), '教师直接访问管理员路由被拒绝并返回教师工作台')
  await logout()
  await page.getByRole('tab', { name: '注册', exact: true }).click()
  await panel.getByPlaceholder('请输入用户名（3-50字符）', { exact: true }).fill('audit_registered')
  await panel.getByPlaceholder('请输入密码（至少6字符）', { exact: true }).fill('Register123')
  await panel.getByPlaceholder('请再次输入密码', { exact: true }).fill('Register123')
  await panel.getByRole('button', { name: '注册', exact: true }).click()
  await page.getByText('用户名已存在', { exact: true }).waitFor()
  check((await state()).users.filter(u => u.username === 'audit_registered').length === 1, '重复教师注册被阻止')
  await page.getByRole('tab', { name: '登录', exact: true }).click()
  await page.getByRole('button', { name: '填入管理员账号', exact: true }).click()
  await page.getByRole('button', { name: '登录', exact: true }).click()
  await page.waitForURL('**/admin/users')
  console.log(JSON.stringify({ phase: 'registration-complete', results }, null, 2))
}
